arguments.content:
:root {
  --primary-color: #0A1628; /* Deep navy */
  --secondary-color: #007982; /* Teal */
  --accent-color: #C8A97E; /* Gold */
  --bg-color: #FFFFFF;
  --bg-alt: #F4F5F7;
  --text-main: #2D3748;
  --text-light: #718096;
  --border-color: #E2E8F0;

  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 6rem;

  --container-width: 1280px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-color);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  color: var(--primary-color);
  line-height: 1.2;
}

h1 { font-size: 3.5rem; letter-spacing: -0.02em; margin-bottom: var(--spacing-sm); }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; margin-bottom: var(--spacing-md); }
h3 { font-size: 1.75rem; margin-bottom: var(--spacing-sm); }
h4 { font-size: 1.25rem; margin-bottom: var(--spacing-xs); }

p {
  margin-bottom: var(--spacing-sm);
  color: var(--text-main);
}

a {
  color: var(--secondary-color);
  text-decoration: none;
  transition: color 0.3s ease;
}
a:hover {
  color: var(--primary-color);
}

ul {
  list-style: none;
}

.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.section {
  padding: var(--spacing-xl) 0;
}
.section.bg-alt {
  background-color: var(--bg-alt);
}
.section.bg-dark {
  background-color: var(--primary-color);
  color: #FFF;
}
.section.bg-dark h2, .section.bg-dark h3, .section.bg-dark p {
  color: #FFF;
}

.btn {
  display: inline-block;
  padding: 0.75rem 2rem;
  font-weight: 600;
  border: 2px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.3s ease;
}
.btn-primary {
  background-color: var(--secondary-color);
  color: #FFF;
}
.btn-primary:hover {
  background-color: #005f66;
  color: #FFF;
}
.btn-outline {
  border-color: #FFF;
  color: #FFF;
}
.btn-outline:hover {
  background-color: #FFF;
  color: var(--primary-color);
}
.btn-link {
  color: var(--secondary-color);
  font-weight: 600;
  padding: 0;
  display: inline-flex;
  align-items: center;
}
.btn-link:after {
  content: '→';
  margin-left: 0.5rem;
  transition: transform 0.3s;
}
.btn-link:hover:after {
  transform: translateX(4px);
}

/* Header & Navigation */
header {
  background-color: #FFF;
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}
.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary-color);
  letter-spacing: -0.02em;
}
.nav-links {
  display: flex;
  gap: var(--spacing-md);
  align-items: center;
}
.nav-item {
  position: relative;
}
.nav-item > a {
  color: var(--primary-color);
  font-weight: 600;
  padding: var(--spacing-sm) 0;
  display: block;
}
.nav-item > a:hover {
  color: var(--secondary-color);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 1000px;
  background: #FFF;
  box-shadow: 0 10px 30px rgba(10, 22, 40, 0.1);
  padding: var(--spacing-lg);
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--spacing-lg);
  border-top: 2px solid var(--secondary-color);
}
.nav-item.has-dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
}
.mega-column h4 {
  font-size: 0.875rem;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: var(--spacing-sm);
  letter-spacing: 0.05em;
}
.mega-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-sm);
}
.mega-list-single {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}
.mega-list a, .mega-list-single a {
  color: var(--text-main);
  font-weight: 500;
  font-size: 0.95rem;
}
.mega-list a:hover, .mega-list-single a:hover {
  color: var(--secondary-color);
}
.mobile-toggle {
  display: none;
  font-size: 1.5rem;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--primary-color);
}

/* Hero Section */
.hero {
  position: relative;
  height: 600px;
  background-color: var(--primary-color);
  display: flex;
  align-items: center;
  color: #FFF;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(90deg, rgba(10,22,40,0.9) 0%, rgba(10,22,40,0.4) 100%);
  z-index: 1;
}
/* Placeholder image styling */
.hero-image {
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  object-fit: cover;
  opacity: 0.6;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}
.hero h1 {
  color: #FFF;
}
.hero p {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
  color: #E2E8F0;
}

/* Announcement Banner */
.announcement {
  background-color: var(--secondary-color);
  color: #FFF;
  padding: 0.75rem 0;
  text-align: center;
  font-weight: 500;
}
.announcement a {
  color: #FFF;
  text-decoration: underline;
  margin-left: var(--spacing-sm);
}

/* Feature Grid */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-md);
}
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-md);
}

/* Cards */
.card {
  background: #FFF;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.05);
}
.card-img {
  width: 100%;
  height: 200px;
  object-fit: cover;
  background-color: #CBD5E0; /* placeholder */
}
.card-content {
  padding: var(--spacing-md);
}
.card-tag {
  font-size: 0.75rem;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--secondary-color);
  margin-bottom: var(--spacing-xs);
  display: block;
}
.card-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-sm);
}

/* Tabs */
.tabs-container {
  display: flex;
  gap: var(--spacing-lg);
  min-height: 400px;
}
.tabs-nav {
  flex: 0 0 300px;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border-color);
}
.tab-btn {
  padding: var(--spacing-md);
  text-align: left;
  background: none;
  border: none;
  border-right: 3px solid transparent;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-light);
  cursor: pointer;
  transition: all 0.3s ease;
  margin-right: -1px;
}
.tab-btn:hover {
  color: var(--primary-color);
}
.tab-btn.active {
  color: var(--primary-color);
  border-right-color: var(--secondary-color);
}
.tab-content {
  flex: 1;
  padding: var(--spacing-md) 0;
  display: none;
}
.tab-content.active {
  display: block;
  animation: fadeIn 0.5s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Newsletter */
.newsletter-form {
  display: flex;
  gap: var(--spacing-sm);
  max-width: 500px;
}
.newsletter-input {
  flex: 1;
  padding: 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: 4px;
}

/* Footer */
footer {
  background-color: var(--primary-color);
  color: #FFF;
  padding: var(--spacing-lg) 0 var(--spacing-md);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}
.footer-col h4 {
  color: #FFF;
  margin-bottom: var(--spacing-sm);
}
.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}
.footer-col a {
  color: #CBD5E0;
}
.footer-col a:hover {
  color: #FFF;
}
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--spacing-md);
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #A0AEC0;
  font-size: 0.875rem;
}
.footer-legal {
  display: flex;
  gap: var(--spacing-md);
}
.footer-legal a {
  color: #A0AEC0;
}
.footer-legal a:hover {
  color: #FFF;
}

/* Page Header */
.page-header {
  background-color: var(--primary-color);
  color: #FFF;
  padding: var(--spacing-xl) 0 var(--spacing-lg);
}
.page-header h1 {
  color: #FFF;
  margin-bottom: var(--spacing-sm);
}

/* Capability List */
.capability-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-lg);
}
.capability-item h3 {
  color: var(--secondary-color);
  margin-bottom: var(--spacing-xs);
}

/* Sidebar layout */
.with-sidebar {
  display: grid;
  grid-template-columns: 3fr 1fr;
  gap: var(--spacing-xl);
}
.sidebar-box {
  background: var(--bg-alt);
  padding: var(--spacing-md);
  border-radius: 4px;
}
.sidebar-box ul {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

/* Carousel */
.carousel {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  gap: var(--spacing-md);
  padding-bottom: var(--spacing-sm);
}
.carousel-item {
  flex: 0 0 300px;
  scroll-snap-align: start;
}

/* Media Queries */
@media (max-width: 992px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .tabs-container { flex-direction: column; }
  .tabs-nav { flex: none; flex-direction: row; border-right: none; border-bottom: 1px solid var(--border-color); overflow-x: auto; }
  .tab-btn { border-right: none; border-bottom: 3px solid transparent; white-space: nowrap; margin-right: 0; margin-bottom: -1px; }
  .tab-btn.active { border-right-color: transparent; border-bottom-color: var(--secondary-color); }
  .with-sidebar { grid-template-columns: 1fr; }
  .mega-menu { display: none; } /* Hide desktop mega menu on tablet/mobile */
}
@media (max-width: 768px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
  .grid-3, .grid-2, .capability-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: var(--spacing-md); }
  .footer-bottom { flex-direction: column; gap: var(--spacing-sm); text-align: center; }
  .nav-links { display: none; position: absolute; top: 100%; left: 0; right: 0; background: #FFF; flex-direction: column; padding: var(--spacing-md); gap: 0; border-bottom: 1px solid var(--border-color); box-shadow: 0 10px 20px rgba(0,0,0,0.1); }
  .nav-links.active { display: flex; }
  .nav-item { width: 100%; border-bottom: 1px solid var(--border-color); }
  .nav-item:last-child { border-bottom: none; }
  .nav-item > a { padding: var(--spacing-md) 0; }
  .mobile-toggle { display: block; }

  /* Mobile accordion */
  .mobile-subnav { display: none; padding-left: var(--spacing-md); padding-bottom: var(--spacing-sm); }
  .mobile-subnav.active { display: block; }
  .mobile-accordion-btn { position: absolute; right: 0; top: 15px; background: none; border: none; font-size: 1.2rem; padding: 10px; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Navigation Toggle
  const mobileToggle = document.getElementById('mobile-toggle');
  const navLinks = document.getElementById('nav-links');

  if (mobileToggle && navLinks) {
    mobileToggle.addEventListener('click', () => {
      navLinks.classList.toggle('active');
    });
  }

  // Mobile Accordion
  const accordionBtns = document.querySelectorAll('.mobile-accordion-btn');
  accordionBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const subnav = btn.nextElementSibling;
      if (subnav) {
        subnav.classList.toggle('active');
        btn.textContent = subnav.classList.contains('active') ? '−' : '+';
      }
    });
  });

  // Tabs for What We Do
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active class from all
      tabBtns.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.classList.remove('active'));

      // Add active class to clicked
      btn.classList.add('active');
      const targetId = btn.getAttribute('data-target');
      const targetContent = document.getElementById(targetId);
      if (targetContent) {
        targetContent.classList.add('active');
      }
    });
  });

  // Newsletter form prevention
  const newsletterForm = document.getElementById('newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      alert('Thanks for subscribing to Our Take Newsletter!');
    });
  }
});
